DH = [10107,38937,17185,28919,2776,13358,48485,8204,12726,26855,14895,10184,37350,39581,33286,57678,9317,34884,43241,25416,59212,2111,13552,13665,27753,39907,59706,65191,52203,4528,7284,45195,55523,51089,7283,39856,47242,14557,48631,22987,43142,10685,30427,28817,41155,17774,28749,37183,11926,51381,42828,664,46183,47440,35243,19177,31386,63474,8527,36644,16018,26365,28693,47522,55857,63879,56651,30729,7029,32163,20056,13200,4632,14606,33719,50722,5816,8736,59699,15159,19149,17137,10666,11244,8266,14015,55910,54993,49376,57817,19928,64265,61969,42026,18477,17986,40894,943]
