assert len(DH)==98 and len(INV)==98, (len(DH),len(INV))
N = sum(v*B**i for i,v in enumerate(DH))
inv = sum(v*B**i for i,v in enumerate(INV))
prod = N*inv
qhat = prod // (B**98)
ql = []
x = qhat
while x>0:
    ql.append(x % B); x//=B
print("qhat limb count:", len(ql))
print("qhat lo12:", ql[:12])
print("TRUEQ lo12:", TRUEQ[:12])
m = min(len(ql), len(TRUEQ))
diffpos=[i for i in range(m) if ql[i]!=TRUEQ[i]]
print("first diff pos:", diffpos[0] if diffpos else "NONE", "numdiff:", len(diffpos))
print("qhat==TRUEQ?", ql[:len(TRUEQ)]==TRUEQ[:len(ql)] and len(ql)==len(TRUEQ))
print("ql[:5]=",ql[:5]," TRUEQ[:5]=",TRUEQ[:5])
# Also compute inverse magnitude: we can derive D_high from the relationship if we had it.
# Instead verify: if qhat were correct, qhat * B^98 should be close to N*inv. Check residual.
print("prod bits:", prod.bit_length(), " expected ~", 98*16 + 98*16)
